"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { BadgeCheck, Clock3, MessageSquare, Building2 } from "lucide-react";
import { chatService } from "@/lib/services/chat.service";
import type { Property } from "@/types/property";

// Owner aggregate stats (response rate/time, listing count, member-since) live on the `users`
// doc in production (docs/01-database-schema.md). Deterministic mock values here stand in until
// Phase 12 wires the real query.
function ownerStats(ownerId: string) {
  let h = 0;
  for (let i = 0; i < ownerId.length; i++) h = (h * 31 + ownerId.charCodeAt(i)) >>> 0;
  return {
    listings: 3 + (h % 12),
    responseRate: 80 + (h % 20),
    responseTimeHrs: 1 + (h % 6),
    memberSinceYear: 2021 + (h % 4),
  };
}

export function OwnerCard({ property }: { property: Property }) {
  const router = useRouter();
  const stats = ownerStats(property.ownerId);
  const initials = property.ownerName
    .split(" ")
    .map((n) => n[0])
    .join("")
    .slice(0, 2);

  function contact() {
    const roomId = chatService.getOrCreateRoomForProperty({
      propertyId: property.id,
      propertyTitle: property.title,
      ownerName: property.ownerName,
      ownerRole: property.postedBy,
    });
    router.push(`/messages?room=${roomId}`);
  }

  return (
    <div className="rounded-2xl border border-border bg-white p-5">
      <div className="flex items-center gap-3">
        <span className="flex h-12 w-12 items-center justify-center rounded-full bg-brand-navy-light text-base font-bold text-brand-navy">
          {initials}
        </span>
        <div className="min-w-0">
          <p className="flex items-center gap-1 text-sm font-bold text-foreground">
            {property.ownerName}
            {property.ownerVerified && <BadgeCheck className="h-4 w-4 shrink-0 text-emerald-600" />}
          </p>
          <p className="text-xs capitalize text-muted-foreground">{property.postedBy}</p>
        </div>
      </div>

      <dl className="mt-4 grid grid-cols-3 gap-2 border-y border-border py-3 text-center">
        <div>
          <dt className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground">Listings</dt>
          <dd className="mt-0.5 text-sm font-bold text-foreground">{stats.listings}</dd>
        </div>
        <div>
          <dt className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground">Response</dt>
          <dd className="mt-0.5 text-sm font-bold text-foreground">{stats.responseRate}%</dd>
        </div>
        <div>
          <dt className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground">Since</dt>
          <dd className="mt-0.5 text-sm font-bold text-foreground">{stats.memberSinceYear}</dd>
        </div>
      </dl>

      <p className="mt-3 flex items-center gap-1.5 text-xs text-muted-foreground">
        <Clock3 className="h-3.5 w-3.5" /> Typically responds within {stats.responseTimeHrs}h
      </p>

      <div className="mt-4 flex gap-2">
        <button
          type="button"
          onClick={contact}
          className="inline-flex flex-1 items-center justify-center gap-1.5 rounded-lg bg-brand-navy py-2.5 text-xs font-semibold text-white hover:bg-brand-navy-dark"
        >
          <MessageSquare className="h-3.5 w-3.5" /> Contact
        </button>
        <Link
          href={`/properties?owner=${property.ownerId}`}
          className="inline-flex flex-1 items-center justify-center gap-1.5 rounded-lg border border-border py-2.5 text-xs font-semibold text-foreground hover:bg-muted"
        >
          <Building2 className="h-3.5 w-3.5" /> All Properties
        </Link>
      </div>
    </div>
  );
}
